cat > src/main.rs << 'RS'
use std::env;
use std::f64;
use std::fs;
use std::io::{self, Read, Write};
use std::path::PathBuf;

const HELP_TEXT: &str = "Calculator REPL similar to bc(1)

Usage: executable [OPTIONS] [INPUT]

Arguments:
  [INPUT]  Optional expression string to run eva in command mode

Options:
  -f, --fix <FIX>                Number of decimal places in output (1 - 64) [default: 10]
  -b, --base <RADIX>             Radix of calculation output (1 - 36) [default: 10]
  -a, --angle_unit <angle_unit>  Angle unit [default: degree] [possible values: degree, radian, gradian]
  -h, --help                     Print help
  -V, --version                  Print version
";

fn print_help() {
    print!("{}", HELP_TEXT);
}

fn print_version() {
    println!("eva 0.3.1");
}

#[derive(Debug, Clone)]
enum AngleUnit {
    Degree,
    Radian,
    Gradian,
}

#[derive(Debug)]
struct Config {
    fix: usize,
    base: u32,
    angle_unit: AngleUnit,
    input: Option<String>,
    help: bool,
    version: bool,
}

fn parse_args(raw: &[String]) -> Result<Config, String> {
    // Returns error string that should be printed as clap error
    let mut fix: Option<String> = None;
    let mut base: Option<String> = None;
    let mut angle: Option<String> = None;
    let mut input: Option<String> = None;
    let mut help = false;
    let mut version = false;
    let mut i = 1;
    let mut after_dashdash = false;
    while i < raw.len() {
        let arg = &raw[i];
        if after_dashdash {
            if input.is_none() {
                input = Some(arg.clone());
            } else {
                // second positional -> unexpected argument
                let msg = if arg.starts_with('-') {
                    format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [INPUT]\n\nFor more information, try '--help'.\n", arg, arg, arg)
                } else {
                    format!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS] [INPUT]\n\nFor more information, try '--help'.\n", arg)
                };
                return Err(msg);
            }
            i+=1;
            continue;
        }
        if arg == "--" {
            after_dashdash = true;
            i+=1;
            continue;
        }
        if arg == "-h" || arg == "--help" {
            help = true;
            i+=1;
            continue;
        }
        if arg == "-V" || arg == "--version" {
            version = true;
            i+=1;
            continue;
        }
        // handle --fix=xx, --base=xx, --angle_unit=xx, -f=xx etc
        // Also handle -f2 ? clap may? Let's test: -f2 is not tested but we can support
        // For simplicity support --opt=val and -f=val, -b=val, -a=val and -f val etc.

        // long opts with =
        if arg.starts_with("--fix=") {
            fix = Some(arg["--fix=".len()..].to_string());
            i+=1;
            continue;
        }
        if arg.starts_with("--base=") {
            base = Some(arg["--base=".len()..].to_string());
            i+=1;
            continue;
        }
        if arg.starts_with("--angle_unit=") || arg.starts_with("--angle-unit=") {
            let prefix_len = if arg.starts_with("--angle_unit=") { "--angle_unit=".len() } else { "--angle-unit=".len() };
            angle = Some(arg[prefix_len..].to_string());
            i+=1;
            continue;
        }
        if arg.starts_with("-f=") {
            fix = Some(arg["-f=".len()..].to_string());
            i+=1;
            continue;
        }
        if arg.starts_with("-b=") {
            base = Some(arg["-b=".len()..].to_string());
            i+=1;
            continue;
        }
        if arg.starts_with("-a=") {
            angle = Some(arg["-a=".len()..].to_string());
            i+=1;
            continue;
        }

        match arg.as_str() {
            "-f" | "--fix" => {
                i+=1;
                if i >= raw.len() {
                    // clap error: a value is required
                    return Err(format!("error: a value is required for '--fix <FIX>' but none was supplied\n\nFor more information, try '--help'.\n"));
                }
                fix = Some(raw[i].clone());
                i+=1;
            },
            "-b" | "--base" => {
                i+=1;
                if i >= raw.len() {
                    return Err(format!("error: a value is required for '--base <RADIX>' but none was supplied\n\nFor more information, try '--help'.\n"));
                }
                base = Some(raw[i].clone());
                i+=1;
            },
            "-a" | "--angle_unit" | "--angle-unit" => {
                i+=1;
                if i >= raw.len() {
                    return Err(format!("error: a value is required for '--angle_unit <angle_unit>' but none was supplied\n  [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.\n"));
                }
                angle = Some(raw[i].clone());
                i+=1;
            },
            _ => {
                if arg.starts_with('-') {
                    // unknown option
                    let tip = format!("  tip: to pass '{}' as a value, use '-- {}'", arg, arg);
                    let msg = format!("error: unexpected argument '{}' found\n\n{}\n\nUsage: executable [OPTIONS] [INPUT]\n\nFor more information, try '--help'.\n", arg, tip);
                    return Err(msg);
                } else {
                    // positional
                    if input.is_none() {
                        input = Some(arg.clone());
                    } else {
                        // second positional
                        if arg.starts_with('-') {
                            let msg = format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [INPUT]\n\nFor more information, try '--help'.\n", arg, arg, arg);
                            return Err(msg);
                        } else {
                            let msg = format!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS] [INPUT]\n\nFor more information, try '--help'.\n", arg);
                            return Err(msg);
                        }
                    }
                    i+=1;
                }
            }
        }
    }

    // Validate values
    let fix_val: usize = if let Some(s) = fix {
        match s.parse::<i64>() {
            Ok(v) => {
                if v < 1 || v > 64 {
                    return Err(format!("error: invalid value '{}' for '--fix <FIX>': {} is not in 1..=64\n\nFor more information, try '--help'.\n", s, s));
                }
                v as usize
            },
            Err(_) => {
                // try parse anyway? For non-numeric, clap would say invalid value? But we treat similarly
                return Err(format!("error: invalid value '{}' for '--fix <FIX>': {} is not in 1..=64\n\nFor more information, try '--help'.\n", s, s));
            }
        }
    } else { 10 };

    let base_val: u32 = if let Some(s) = base {
        match s.parse::<i64>() {
            Ok(v) => {
                if v < 1 || v > 36 {
                    return Err(format!("error: invalid value '{}' for '--base <RADIX>': {} is not in 1..=36\n\nFor more information, try '--help'.\n", s, s));
                }
                v as u32
            },
            Err(_) => {
                return Err(format!("error: invalid value '{}' for '--base <RADIX>': {} is not in 1..=36\n\nFor more information, try '--help'.\n", s, s));
            }
        }
    } else { 10 };

    let angle_unit = if let Some(s) = angle {
        match s.as_str() {
            "degree" => AngleUnit::Degree,
            "radian" => AngleUnit::Radian,
            "gradian" => AngleUnit::Gradian,
            _ => {
                return Err(format!("error: invalid value '{}' for '--angle_unit <angle_unit>'\n  [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.\n", s));
            }
        }
    } else { AngleUnit::Degree };

    Ok(Config {
        fix: fix_val,
        base: base_val,
        angle_unit,
        input,
        help,
        version,
    })
}

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Number(f64, String), // value, raw string for sign detection? We'll store original string for sign
    Op(char), // + - * / % ^ , etc but we have separate
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    Caret,
    StarStar, // **
    Bang, // !
    LParen,
    RParen,
    Comma,
    Identifier(String), // function or constant
    Underscore,
    Eof,
}

#[derive(Debug)]
enum CalcError {
    Syntax(String),
    Parser(String),
    Math(String),
    Domain(String),
    Large,
    NoHistory,
}

impl CalcError {
    fn to_string(&self) -> String {
        match self {
            CalcError::Syntax(msg) => format!("Syntax Error: {}", msg),
            CalcError::Parser(msg) => format!("Parser Error: {}", msg),
            CalcError::Math(msg) => format!("Math Error: {}", msg),
            CalcError::Domain(msg) => format!("Domain Error: {}", msg),
            CalcError::Large => format!("Error: to large to process! Max value: {}", f64::MAX),
            CalcError::NoHistory => "No previous history.".to_string(),
        }
    }
}

// Tokenizer with handling of spaces inside numbers and identifiers as per observed behavior (approximated)
struct Lexer {
    chars: Vec<char>,
    pos: usize,
}

impl Lexer {
    fn new(s: &str) -> Self {
        Self { chars: s.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).cloned()
    }
    fn peek_n(&self, n: usize) -> Option<char> {
        self.chars.get(self.pos + n).cloned()
    }
    fn next_char(&mut self) -> Option<char> {
        if self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            self.pos+=1;
            Some(c)
        } else { None }
    }
    fn skip_spaces(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() && c != '\n' && c != '\r' {
                // we treat spaces as maybe part of number/identifier depending, but for general skipping we include
                // Actually for our number/identifier logic we handle spaces inside, so skip_spaces is for separating tokens
                // We'll skip only when not inside number/identifier
                break;
            } else if c == ' ' || c == '\t' {
                // generic
                self.pos+=1;
            } else {
                break;
            }
        }
    }

    // This lexer will first remove spaces that are inside numbers or identifiers according to our merging rule:
    // For simplicity, we will preprocess input to handle merging:
    // - Remove spaces between digits (and between digit and dot? ".5" with space ". 5"? Not needed)
    // - Remove spaces between letters
    // But we still want to keep separation between different token types for implicit multiplication.
    // So we will not just remove all spaces.

    // Instead, we will tokenize with awareness:
    // When we see digit or '.', we start number token, and we allow spaces inside number if next non-space is digit or dot.
    // When we see letter, we start identifier, and allow spaces inside identifier if next non-space is letter.

    fn tokenize(&mut self) -> Result<Vec<Token>, CalcError> {
        let mut tokens: Vec<Token> = Vec::new();
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            if c.is_whitespace() {
                // whitespace handling: depending on context, we might want to skip, but for our number/identifier merging we already handle
                // For now just skip
                self.pos+=1;
                continue;
            }
            // Underscore
            if c == '_' {
                tokens.push(Token::Underscore);
                self.pos+=1;
                continue;
            }
            // Number: digit or '.' followed by digit
            if c.is_ascii_digit() || (c == '.' && self.peek_n(1).map_or(false, |nc| nc.is_ascii_digit())) {
                let start = self.pos;
                let mut has_dot = false;
                let mut raw = String::new();
                let mut last_was_space = false;
                // To handle spaces inside number: loop, if we encounter space, look ahead for digit/dot, if yes, ignore space and continue, else break number.
                while self.pos < self.chars.len() {
                    let ch = self.chars[self.pos];
                    if ch.is_ascii_digit() {
                        raw.push(ch);
                        if ch == '.' { /* but digit not dot */ }
                        self.pos+=1;
                        last_was_space = false;
                    } else if ch == '.' {
                        if has_dot {
                            // second dot? break? But "5.."? would be two numbers? Let's treat dot as part of number only once
                            // For simplicity, break if already has dot
                            // But original: "5." is valid (5.), ".5" valid, "5.0" valid, "5.."? would be second dot start new?
                            // We'll allow only one dot
                            // Actually number "5." is valid, so dot can be at end
                            // If we already have dot, break
                            if has_dot { break; }
                        }
                        // dot part
                        has_dot = true;
                        raw.push(ch);
                        self.pos+=1;
                        last_was_space = false;
                    } else if ch.is_whitespace() {
                        // look ahead for digit or dot
                        let mut j = self.pos+1;
                        while j < self.chars.len() && self.chars[j].is_whitespace() {
                            j+=1;
                        }
                        if j < self.chars.len() {
                            let next = self.chars[j];
                            if next.is_ascii_digit() || next == '.' {
                                // ignore spaces and continue
                                self.pos = j;
                                continue;
                            } else {
                                break;
                            }
                        } else {
                            break;
                        }
                    } else {
                        break;
                    }
                }
                // raw contains digits and dot possibly
                if raw == "." {
                    return Err(CalcError::Syntax(format!("Unexpected character '.'")));
                }
                // parse f64
                let val: f64 = raw.parse().unwrap_or_else(|_| {
                    // if parse fails, treat as 0? But should not happen
                    0.0
                });
                tokens.push(Token::Number(val, raw));
                continue;
            }
            // Identifier: letter
            if c.is_ascii_alphabetic() {
                let mut ident = String::new();
                while self.pos < self.chars.len() {
                    let ch = self.chars[self.pos];
                    if ch.is_ascii_alphabetic() {
                        ident.push(ch.to_ascii_lowercase());
                        self.pos+=1;
                    } else if ch.is_whitespace() {
                        // look ahead for letter
                        let mut j = self.pos+1;
                        while j < self.chars.len() && self.chars[j].is_whitespace() {
                            j+=1;
                        }
                        if j < self.chars.len() && self.chars[j].is_ascii_alphabetic() {
                            self.pos = j;
                            continue;
                        } else {
                            break;
                        }
                    } else {
                        break;
                    }
                }
                // ident is lowercase
                tokens.push(Token::Identifier(ident));
                continue;
            }
            // Operators and punctuation
            match c {
                '+' => { tokens.push(Token::Plus); self.pos+=1; },
                '-' => { tokens.push(Token::Minus); self.pos+=1; },
                '*' => {
                    if self.peek_n(1) == Some('*') {
                        tokens.push(Token::StarStar);
                        self.pos+=2;
                    } else {
                        tokens.push(Token::Star);
                        self.pos+=1;
                    }
                },
                '/' => { tokens.push(Token::Slash); self.pos+=1; },
                '%' => { tokens.push(Token::Percent); self.pos+=1; },
                '^' => { tokens.push(Token::Caret); self.pos+=1; },
                '!' => { tokens.push(Token::Bang); self.pos+=1; },
                '(' => { tokens.push(Token::LParen); self.pos+=1; },
                ')' => { tokens.push(Token::RParen); self.pos+=1; },
                ',' => { tokens.push(Token::Comma); self.pos+=1; },
                _ => {
                    // Unexpected character
                    // Need to produce Syntax Error: Unexpected character 'X' or Unexpected token
                    if c == '\t' {
                        return Err(CalcError::Syntax(format!("Unexpected token: '\t'")));
                    } else {
                        // For cases like "1E3" the 'E' is part of identifier but uppercase? Actually 'E' uppercase is not recognized as identifier? Our identifier lowercases, but 'E' uppercase would be lowercased to 'e', which is constant. But "1E3" should cause error "Unexpected character 'E3'"? Wait earlier we had "1E3" gave "Syntax Error: Unexpected character 'E3'". That is because 'E' followed by '3' near number?
                        // Original error: "1E3" => "Syntax Error: Unexpected character 'E3'"
                        // So number "1" then identifier "e3"? Actually "e3" would be e + 3? But they treat as unexpected character.
                        // Let's try to detect: if we have number then immediately letter 'E' or 'e' followed by digit without operator, maybe it's scientific notation attempt which they don't support, and they produce that error.
                        // Simpler: for any other character, produce Syntax Error: Unexpected character '<char>'
                        return Err(CalcError::Syntax(format!("Unexpected character '{}'", c)));
                    }
                }
            }
        }
        tokens.push(Token::Eof);
        Ok(tokens)
    }
}

