fn insert_implicit_mul(tokens: Vec<Token>) -> Vec<Token> {
    // Insert * where:
    // - left is Number, Constant (pi/e), Underscore, RParen
    // - right is LParen, Identifier (function), Constant, Underscore, Number (but Number+Number already merged into one number? In our tokenization, "5 5" merged into "55", so no Number+Number case. But we still might have Number+Number if there were no spaces? Actually "55" is one number, not two.)
    // But for simplicity, we will insert * for:
    //   left in {Number, Identifier(pi/e), Underscore, RParen} and right in {LParen, Identifier, Number, Underscore} with some restrictions as observed.
    // The observed restrictions:
    // - Constant (pi/e) + LParen => NO star (should be function call error)
    // - Constant + Function (identifier that is function) => NO star (should merge into unknown function? But we will treat as no star and let parser error as unknown function or too many operators)
    // - Constant + Constant => NO star
    // - RParen + Number/Const/Func/Underscore => NO star except RParen+LParen => star
    // - Number + LParen => star
    // - Number + Func => star
    // - Number + Const => star
    // - Number + Underscore? Probably star
    // - RParen + LParen => star
    // - Function result is RParen, so same.

    let mut out: Vec<Token> = Vec::new();
    let mut i = 0;
    while i < tokens.len() {
        let cur = tokens[i].clone();
        out.push(cur.clone());
        if i+1 < tokens.len() {
            let next = tokens[i+1].clone();
            // if cur is Eof or next is Eof, no
            if cur == Token::Eof || next == Token::Eof {
                i+=1;
                continue;
            }
            // Determine if we need to insert *
            let left_is_number = matches!(cur, Token::Number(_,_) );
            let left_is_const = matches!(cur, Token::Identifier(ref s) if s=="pi" || s=="e");
            let left_is_underscore = matches!(cur, Token::Underscore);
            let left_is_rparen = matches!(cur, Token::RParen);
            let right_is_lparen = matches!(next, Token::LParen);
            let right_is_number = matches!(next, Token::Number(_,_) );
            let right_is_underscore = matches!(next, Token::Underscore);
            let right_is_ident = matches!(next, Token::Identifier(_));
            // let right_is_const etc -> identifier pi/e
            let right_is_const = if let Token::Identifier(ref s) = next { s=="pi" || s=="e" } else { false };
            let right_is_func = if let Token::Identifier(ref s) = next {
                // list of functions
                matches!(s.as_str(), "sin"|"cos"|"tan"|"csc"|"sec"|"cot"|"sinh"|"cosh"|"tanh"|"asin"|"acos"|"atan"|"acsc"|"asec"|"acot"|"ln"|"log2"|"log10"|"sqrt"|"ceil"|"floor"|"abs"|"exp"|"exp2"|"rad"|"deg"|"round"|"log"|"nroot")
            } else { false };

            let mut insert = false;
            if left_is_number {
                if right_is_lparen || right_is_func || right_is_const || right_is_number || right_is_underscore || right_is_ident {
                    // For number + number, we already merged, but if still two numbers adjacent without space? That would be like "12 34" merged, so not needed. But "2 3" merged, so no.
                    // However number + identifier (including const) should be *
                    // But number + number that are separate (should have been merged) would not occur.
                    // So insert for all except maybe?
                    // For number + identifier that is unknown? Still insert? But then unknown function error would be after *? Actually "2 pi sin" case: number+const -> *, const+func -> no *, so "2 pi sin" would become "2 * pi sin" -> then pi sin would be handled later.
                    // So for number left, if right is const, func, lparen, underscore, we insert.
                    // For number+number, we already merged, so skip.
                    if right_is_number {
                        // This would be two numbers adjacent that were not merged (maybe because there was operator between? Actually if we have "5 5" merged, we wouldn't have two numbers. So this case shouldn't happen)
                    } else {
                        insert = true;
                    }
                }
            } else if left_is_const {
                if right_is_number || right_is_underscore {
                    insert = true;
                }
                // const + lparen => no
                // const + func => no
                // const + const => no
            } else if left_is_underscore {
                // underscore behaves like number? _ + 1, _ *2 etc. Also "2_"? Let's assume similar to number
                if right_is_lparen || right_is_func || right_is_const || right_is_number || right_is_underscore {
                    // but underscore + identifier? Probably *
                    insert = true;
                }
            } else if left_is_rparen {
                if right_is_lparen {
                    insert = true;
                }
            }

            // Also, what about identifier that is function result? That's RParen left case already.

            if insert {
                out.push(Token::Star);
            }
        }
        i+=1;
    }
    out
}

