                rad.cos()
            },
            "tan" => {
                let rad = match self.angle_unit {
                    AngleUnit::Degree => arg * std::f64::consts::PI / 180.0,
                    AngleUnit::Radian => arg,
                    AngleUnit::Gradian => arg * std::f64::consts::PI / 180.0,
