            },
            "cot" => {
                let rad = match self.angle_unit {
                    AngleUnit::Degree => arg * std::f64::consts::PI / 180.0,
                    AngleUnit::Radian => arg,
                    AngleUnit::Gradian => arg * std::f64::consts::PI / 180.0,
                };
                let t = rad.tan();
                if t == 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                1.0 / t
            },
            "sinh" => arg.sinh(),
            "cosh" => arg.cosh(),
            "tanh" => arg.tanh(),
            "asin" => {
                if arg < -1.0 || arg > 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                arg.asin()
            },
            "acos" => {
                if arg < -1.0 || arg > 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                arg.acos()
            },
            "atan" => arg.atan(),
            "acsc" => {
                if arg.abs() < 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                (1.0 / arg).asin()
            },
            "asec" => {
                if arg.abs() < 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                (1.0 / arg).acos()
            },
            "acot" => {
                // acot(x) = atan(1/x) ? But for x=0, pi/2
                if arg == 0.0 {
                    std::f64::consts::PI / 2.0
                } else {
                    (1.0 / arg).atan()
                }
            },
            "ln" => {
                if arg <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                arg.ln()
            },
            "log2" => {
                if arg <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                arg.log2()
            },
            "log10" => {
                if arg <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                arg.log10()
            },
            "sqrt" => {
                if arg < 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                arg.sqrt()
            },
            "ceil" => arg.ceil(),
            "floor" => arg.floor(),
            "abs" => arg.abs(),
            "exp" => arg.exp(),
            "exp2" => arg.exp2(),
            "rad" => arg * std::f64::consts::PI / 180.0,
            "deg" => arg * 180.0 / std::f64::consts::PI,
            "round" => {
                // round half away from zero as per observed
                if arg.is_sign_positive() {
                    (arg + 0.5).floor()
                } else {
                    (arg - 0.5).ceil()
                }
            },
            _ => return Err(CalcError::Syntax(format!("Unknown function '{}'", name))),
        };
        if !res.is_finite() {
            return Err(CalcError::Large);
        }
        Ok(res)
    }

    fn eval_func_2(&self, name: &str, a: f64, b: f64) -> Result<f64, CalcError> {
        let res = match name {
            "log" => {
                // log(a,b) = log_b(a) = ln(a)/ln(b)
                if a <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                if b == 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                if b == 0.0 {
                    // ln(b) = -inf, ln(a)/-inf = -0
                    -0.0
                } else {
                    if b <= 0.0 {
                        return Err(CalcError::Domain("Out of bounds!".to_string()));
                    }
                    a.ln() / b.ln()
                }
            },
            "nroot" => {
                // nroot(a,b) = a^(1/b)
                // Domain: a <0 => error (even if b odd, original gives error)
                if a < 0.0 {
                    return Err(CalcError::Domain("Out of bounds!".to_string()));
                }
                // b ==0 handling:
                if b == 0.0 {
                    if a == 0.0 {
                        0.0
                    } else if a == 1.0 {
                        1.0
                    } else {
                        return Err(CalcError::Domain("Out of bounds!".to_string()));
                    }
                } else {
                    a.powf(1.0 / b)
                }
            },
            _ => return Err(CalcError::Syntax(format!("Unknown function '{}'", name))),
        };
        if !res.is_finite() {
            if res == -0.0 { Ok(res) } else { Err(CalcError::Large) }
        } else {
            Ok(res)
        }
    }
}

fn auto_balance(s: &str) -> Result<String, CalcError> {
    let mut open = 0;
    let mut close = 0;
    for c in s.chars() {
        if c == '(' { open+=1; }
        else if c == ')' { close+=1; }
    }
    if close > open {
        return Err(CalcError::Syntax("Mismatched parentheses!".to_string()));
    }
    let mut res = s.to_string();
    for _ in 0..(open-close) {
        res.push(')');
    }
    Ok(res)
}

fn eval_expression(expr: &str, angle_unit: AngleUnit, prev: f64) -> Result<f64, CalcError> {
    let trimmed = expr.trim();
    if trimmed.is_empty() {
        return Ok(0.0);
    }
    // auto balance
    let balanced = auto_balance(trimmed)?;
    let mut lexer = Lexer::new(&balanced);
    let tokens = lexer.tokenize()?;
    let tokens = insert_implicit_mul(tokens);
    let mut parser = Parser::new(tokens, angle_unit, prev);
    parser.parse()
}

fn format_output(value: f64, base: u32, fix: usize) -> String {
    // Handle negative zero sign preservation?
    let is_negative = value.is_sign_negative() && value != 0.0;
    let is_neg_zero = value.is_sign_negative() && value == 0.0;
    // For formatting, we need to round to fix decimal places in base 10 first (as per reverse engineering)
    // For base 10, format directly with fix
    // For other bases, we first round to fix decimal places (base10) then convert.

    // Helper to round to fix decimal places: using format! and parse? Or using round?
    // We'll use: value_rounded = (value * 10^fix).round() / 10^fix ??? But original seems to use binary float rounding that results in e.g., 0.995 f2 =>0.99 due to binary representation.
    // Using format with fixed may give same as original? Let's use formatting that does round half even? Need to mimic.
    // Approach: Use format!("{:.fix$}", value) to get rounded string, then parse back as f64 for further base conversion.
    // For base10 output, we can directly use that formatted string but need to add grouping commas.

    // For base10:
    // - value_rounded for display is value formatted to fix decimal places, with rounding.
    // - Then we need to group integer part with commas.

    // For non-base10:
    // - First round value to fix decimal places in base10 (using same formatting), then parse that rounded value as f64.
    // - Then convert that rounded value to target base.

    // Implementation details for base10 rounding:
    // We'll create rounded value via: let s = format!("{:.fix$}", value); but this may produce "-0.00" for -0? Need to handle.
    // Then parse that s as f64 to get rounded value.

    // For base 10 formatting with grouping:
    // Let's get rounded string s (like "1000.00" or "-10.50")
    // For base10, we need to insert commas every 3 digits in integer part.

    // For non-base10, after rounding, we have rounded f64. Then:
    // integer part = trunc(abs(rounded))
    // fractional = abs(rounded) - integer
    // Convert integer to base string uppercase.
    // If base==1: special handling (infinite loop for non-zero)
    // If integer ==0 and value is -0? Need sign.

    // For base==1:
    // - If integer !=0 => infinite loop (simulate hang) -> loop forever.
    // - If integer ==0: integer string "0"
    // - Fractional: if rounded fractional ==0 => fractional zeros? Actually per observed, for base1:
    //   if integer==0 and fractional==0 => output "0.0" (single zero)
    //   else (fractional !=0) => output "0." + "0" * fix (zeros)
    // And with grouping? For base1, grouping still applies? For integer 0, grouping gave " ,   ,   ,  0" padded.

    // Let's implement generic formatting function.

    if base == 1 {
        // Check integer part
        // First round value to fix decimal places
        let rounded = {
            // use format to round
            // For large values, format may overflow? But base1 only for small? We'll just use formatting
            let s = format!("{:.fix$}", value);
            s.parse::<f64>().unwrap_or(value)
        };
        let abs_rounded = rounded.abs();
        let int_part = abs_rounded.trunc() as u64; // for base1, if int_part !=0, hang
        if int_part != 0 {
            // Simulate original hang: infinite loop
            loop {}
        }
        // integer 0
        let int_str = "0".to_string();
        // fractional check
        let frac = abs_rounded.fract();
        let frac_is_zero = frac < 1e-12; // after rounding to fix decimals, fractional may be 0
        // Actually need to check if rounded value has fractional part ==0 after rounding to fix decimals
        // For base1, if frac_is_zero => output fractional "0"
        // else => "0" * fix
        let frac_str = if frac_is_zero {
            "0".to_string()
        } else {
            "0".repeat(fix)
        };
        // Now format integer part with grouping and padding as per non-base10 rule
        let sign = if rounded.is_sign_negative() { "-" } else { "" };
        // For base1, integer grouping: same as other non-base10
        let grouped_int = format_int_non10(&int_str, sign, base);
        return format!("{}.{}", grouped_int, frac_str);
    }

    if base == 10 {
        // Format rounded to fix
        // Use format with fix, but we need to preserve -0?
        // For -0.0, format!("{:.fix$}", -0.0) gives "-0.00"? Let's check Rust behavior: -0.0 formatted gives "-0.00"? In many languages, -0.0 gives "-0.00". Our earlier test for log(2,0) gave "-0.0000000000" for base10. That matches -0.
        let formatted = format!("{:.fix$}", value);
        // Now formatted is like "-1000.00" or "10.50" etc.
        // Split into sign, integer, fractional
        let (sign_str, rest) = if formatted.starts_with('-') {
            ("-", &formatted[1..])
        } else {
            ("", formatted.as_str())
        };
        let parts: Vec<&str> = rest.split('.').collect();
        let int_part = parts[0];
        let frac_part = if parts.len() > 1 { parts[1] } else { "" };
        // Group integer part
        let grouped_int = group_int_base10(int_part);
        if fix == 0 {
            format!("{}{}", sign_str, grouped_int)
        } else {
            format!("{}{}.{}", sign_str, grouped_int, frac_part)
        }
    } else {
        // non-base10: first round to fix decimal places in base10
        let rounded_str = format!("{:.fix$}", value);
        let rounded_val: f64 = rounded_str.parse().unwrap_or(value);
        // Now convert rounded_val
        let is_neg = rounded_val.is_sign_negative();
        let abs_val = rounded_val.abs();
        let int_part_f = abs_val.trunc();
        let frac_part_f = abs_val.fract();

        // Convert integer part to base
        // For large int_part, may exceed u64, use f64 conversion loop?
        // We'll convert via integer part as u128 if possible, else use f64 loop.

        let int_str = convert_int_to_base(int_part_f, base);
        // Now fractional conversion up to fix digits, truncating
        let mut frac_digits: Vec<char> = Vec::new();
        let mut frac = frac_part_f;
        for _ in 0..fix {
            frac *= base as f64;
            let digit = frac.trunc() as u32;
            let ch = digit_to_char(digit);
