                    println!("{}", out);
                    prev_ans = val;
                    // update prev file
                    let _ = fs::write(&prev_path, format!("{}", prev_ans));
                    continue;
                }
                // add to history file (if not empty)
                // Append line to history file
                if let Ok(mut file) = fs::OpenOptions::new().append(true).open(&history_path) {
                    let _ = writeln!(file, "{}", line);
                }

                match eval_expression(line, config.angle_unit.clone(), prev_ans) {
                    Ok(val) => {
                        let out = format_output(val, config.base, config.fix);
                        println!("{}", out);
                        prev_ans = val;
                        let _ = fs::write(&prev_path, format!("{}", prev_ans));
                    },
                    Err(e) => {
                        // For REPL, errors go to stdout (as per observed)
                        println!("{}", e.to_string());
                    }
                }
            }
        }
    }
}
