fn group_int_base10(s: &str) -> String {
    // s is digits without sign, e.g., "1000"
    if s.is_empty() { return "0".to_string(); }
    let mut result = String::new();
    let mut count = 0;
    for ch in s.chars().rev() {
        if count != 0 && count % 3 == 0 {
            result.push(',');
        }
        result.push(ch);
        count+=1;
    }
    result.chars().rev().collect()
}

fn convert_int_to_base(val: f64, base: u32) -> String {
    if val == 0.0 {
        return "0".to_string();
    }
    // For large values, we may need to handle via f64? We'll convert via u128 if possible, else fallback to iterative division using f64
    // If val <= 2^53, it is exactly representable as integer
    if val <= 9_007_199_254_740_992.0 {
        let mut n = val as u128;
        let mut digits: Vec<char> = Vec::new();
        while n > 0 {
            let d = (n % base as u128) as u32;
            digits.push(digit_to_char(d));
            n /= base as u128;
        }
        digits.into_iter().rev().collect()
    } else {
        // For larger, use f64 division
        let mut n = val;
        let mut digits: Vec<char> = Vec::new();
        while n >= 1.0 {
            let rem = (n % base as f64) as u32;
            digits.push(digit_to_char(rem));
            n = (n / base as f64).trunc();
            if digits.len() > 1000 { break; } // safety
        }
        if digits.is_empty() { return "0".to_string(); }
        digits.into_iter().rev().collect()
    }
}

fn digit_to_char(d: u32) -> char {
    if d < 10 {
        (b'0' + d as u8) as char
    } else {
        (b'A' + (d - 10) as u8) as char
    }
}

fn format_int_non10(int_str: &str, sign: &str, _base: u32) -> String {
    // int_str is e.g., "A" or "100" without sign
    // sign is "" or "-"
    // Need to format with min 10 digit positions (including sign+digits, excluding commas)
    // Steps:
    // - combined = sign + int_str (e.g., "-A" or "A")
    // - digit_positions = combined length (number of non-comma chars)
    // - If digit_positions < 10, pad with spaces to the left to reach 10
    // - Then insert commas every 3 digits from right, counting digit positions (including sign as part of positions? Actually sign is counted as part of digit positions as per earlier analysis)
    // - The padding spaces are part of digit positions.

    let combined = format!("{}{}", sign, int_str);
    let len = combined.chars().count();
    let padded: String = if len < 10 {
        let spaces = " ".repeat(10 - len);
        format!("{}{}", spaces, combined)
    } else {
        combined
    };
    // Now insert commas every 3 from right
    // We have string of length 10+ (or more), consisting of spaces, '-', and alphanum
    // We need to split into groups of 3 from right
    let chars: Vec<char> = padded.chars().collect();
    let mut groups: Vec<String> = Vec::new();
    let mut i = chars.len();
    while i > 0 {
        let start = if i >= 3 { i-3 } else { 0 };
        let group: String = chars[start..i].iter().collect();
        groups.push(group);
        i = start;
    }
    groups.reverse();
    groups.join(",")
}

