#[derive(Debug, Clone)]
enum AngleUnit {
    Degree,
    Radian,
    Gradian,
}

#[derive(Debug)]
struct Config {
    fix: usize,
    base: u32,
    angle_unit: AngleUnit,
    input: Option<String>,
    help: bool,
    version: bool,
}

fn parse_args(raw: &[String]) -> Result<Config, String> {
    let mut fix: Option<String> = None;
    let mut base: Option<String> = None;
    let mut angle: Option<String> = None;
    let mut input: Option<String> = None;
    let mut help = false;
    let mut version = false;
    let mut i = 1;
    let mut after_dashdash = false;
    while i < raw.len() {
        let arg = &raw[i];
        if after_dashdash {
            if input.is_none() {
                input = Some(arg.clone());
            } else {
                let msg = if arg.starts_with('-') {
                    format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [INPUT]\n\nFor more information, try '--help'.\n", arg, arg, arg)
                } else {
                    format!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS] [INPUT]\n\nFor more information, try '--help'.\n", arg)
                };
                return Err(msg);
            }
            i+=1;
            continue;
        }
        if arg == "--" {
            after_dashdash = true;
            i+=1;
            continue;
        }
        if arg == "-h" || arg == "--help" {
            help = true;
            i+=1;
            continue;
        }
        if arg == "-V" || arg == "--version" {
            version = true;
            i+=1;
            continue;
        }
        if arg.starts_with("--fix=") {
            fix = Some(arg["--fix=".len()..].to_string());
            i+=1;
            continue;
        }
        if arg.starts_with("--base=") {
            base = Some(arg["--base=".len()..].to_string());
            i+=1;
            continue;
        }
        if arg.starts_with("--angle_unit=") {
            angle = Some(arg["--angle_unit=".len()..].to_string());
            i+=1;
            continue;
        }
        if arg.starts_with("--angle-unit=") {
            angle = Some(arg["--angle-unit=".len()..].to_string());
            i+=1;
            continue;
        }
        if arg.starts_with("-f=") {
            fix = Some(arg["-f=".len()..].to_string());
            i+=1;
            continue;
        }
        if arg.starts_with("-b=") {
            base = Some(arg["-b=".len()..].to_string());
            i+=1;
            continue;
        }
        if arg.starts_with("-a=") {
            angle = Some(arg["-a=".len()..].to_string());
            i+=1;
            continue;
        }
        match arg.as_str() {
            "-f" | "--fix" => {
                i+=1;
                if i >= raw.len() {
                    return Err(format!("error: a value is required for '--fix <FIX>' but none was supplied\n\nFor more information, try '--help'.\n"));
                }
                fix = Some(raw[i].clone());
                i+=1;
            },
            "-b" | "--base" => {
                i+=1;
                if i >= raw.len() {
                    return Err(format!("error: a value is required for '--base <RADIX>' but none was supplied\n\nFor more information, try '--help'.\n"));
                }
                base = Some(raw[i].clone());
                i+=1;
            },
            "-a" | "--angle_unit" | "--angle-unit" => {
                i+=1;
                if i >= raw.len() {
                    return Err(format!("error: a value is required for '--angle_unit <angle_unit>' but none was supplied\n  [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.\n"));
                }
                angle = Some(raw[i].clone());
                i+=1;
            },
            _ => {
                if arg.starts_with('-') && arg.len() > 1 {
                    let tip = format!("  tip: to pass '{}' as a value, use '-- {}'", arg, arg);
                    let msg = format!("error: unexpected argument '{}' found\n\n{}\n\nUsage: executable [OPTIONS] [INPUT]\n\nFor more information, try '--help'.\n", arg, tip);
                    return Err(msg);
                } else {
                    if input.is_none() {
                        input = Some(arg.clone());
                    } else {
                        let msg = if arg.starts_with('-') {
                            format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [INPUT]\n\nFor more information, try '--help'.\n", arg, arg, arg)
                        } else {
                            format!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS] [INPUT]\n\nFor more information, try '--help'.\n", arg)
                        };
                        return Err(msg);
                    }
                    i+=1;
                }
            }
        }
    }

    let fix_val: usize = if let Some(s) = fix {
        match s.parse::<i64>() {
            Ok(v) => {
                if v < 1 || v > 64 {
                    return Err(format!("error: invalid value '{}' for '--fix <FIX>': {} is not in 1..=64\n\nFor more information, try '--help'.\n", s, s));
                }
                v as usize
            },
            Err(_) => {
                return Err(format!("error: invalid value '{}' for '--fix <FIX>': {} is not in 1..=64\n\nFor more information, try '--help'.\n", s, s));
            }
        }
    } else { 10 };

    let base_val: u32 = if let Some(s) = base {
        match s.parse::<i64>() {
            Ok(v) => {
                if v < 1 || v > 36 {
                    return Err(format!("error: invalid value '{}' for '--base <RADIX>': {} is not in 1..=36\n\nFor more information, try '--help'.\n", s, s));
                }
                v as u32
            },
            Err(_) => {
                return Err(format!("error: invalid value '{}' for '--base <RADIX>': {} is not in 1..=36\n\nFor more information, try '--help'.\n", s, s));
            }
        }
    } else { 10 };

    let angle_unit = if let Some(s) = angle {
        match s.as_str() {
            "degree" => AngleUnit::Degree,
            "radian" => AngleUnit::Radian,
            "gradian" => AngleUnit::Gradian,
            _ => {
                return Err(format!("error: invalid value '{}' for '--angle_unit <angle_unit>'\n  [possible values: degree, radian, gradian]\n\nFor more information, try '--help'.\n", s));
            }
        }
    } else { AngleUnit::Degree };

    Ok(Config {
        fix: fix_val,
        base: base_val,
        angle_unit,
        input,
        help,
        version,
    })
}

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Number(f64, String),
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    Caret,
    StarStar,
    Bang,
    LParen,
    RParen,
    Comma,
    Identifier(String),
    Underscore,
    Eof,
}

#[derive(Debug)]
enum CalcError {
    Syntax(String),
    Parser(String),
    Math(String),
    Domain(String),
    Large,
    NoHistory,
}

impl CalcError {
    fn to_string(&self) -> String {
        match self {
            CalcError::Syntax(msg) => format!("Syntax Error: {}", msg),
            CalcError::Parser(msg) => format!("Parser Error: {}", msg),
            CalcError::Math(msg) => format!("Math Error: {}", msg),
            CalcError::Domain(msg) => format!("Domain Error: {}", msg),
            CalcError::Large => format!("Error: to large to process! Max value: {}", f64::MAX),
            CalcError::NoHistory => "No previous history.".to_string(),
        }
    }
}

struct Lexer {
    chars: Vec<char>,
    pos: usize,
}

impl Lexer {
    fn new(s: &str) -> Self {
        Self { chars: s.chars().collect(), pos: 0 }
    }
    fn peek_n(&self, n: usize) -> Option<char> {
        self.chars.get(self.pos + n).cloned()
    }
    fn tokenize(&mut self) -> Result<Vec<Token>, CalcError> {
        let mut tokens: Vec<Token> = Vec::new();
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            if c.is_whitespace() {
                self.pos+=1;
                continue;
            }
            if c == '_' {
                tokens.push(Token::Underscore);
                self.pos+=1;
                continue;
            }
            if c.is_ascii_digit() || (c == '.' && self.peek_n(1).map_or(false, |nc| nc.is_ascii_digit())) {
                let mut raw = String::new();
                let mut has_dot = false;
                while self.pos < self.chars.len() {
                    let ch = self.chars[self.pos];
                    if ch.is_ascii_digit() {
                        raw.push(ch);
                        self.pos+=1;
                    } else if ch == '.' {
                        if has_dot { break; }
                        has_dot = true;
                        raw.push(ch);
                        self.pos+=1;
                    } else if ch.is_whitespace() {
                        let mut j = self.pos+1;
                        while j < self.chars.len() && self.chars[j].is_whitespace() {
                            j+=1;
                        }
                        if j < self.chars.len() {
                            let next = self.chars[j];
                            if next.is_ascii_digit() || next == '.' {
                                self.pos = j;
                                continue;
                            } else {
                                break;
                            }
                        } else {
                            break;
                        }
                    } else {
                        break;
                    }
                }
                if raw == "." {
                    return Err(CalcError::Syntax(format!("Unexpected character '.'")));
                }
                let val: f64 = raw.parse().unwrap_or(0.0);
                tokens.push(Token::Number(val, raw));
                continue;
            }
            if c.is_ascii_alphabetic() {
                let mut ident = String::new();
                while self.pos < self.chars.len() {
                    let ch = self.chars[self.pos];
                    if ch.is_ascii_alphabetic() {
                        ident.push(ch.to_ascii_lowercase());
                        self.pos+=1;
                    } else if ch.is_whitespace() {
                        let mut j = self.pos+1;
                        while j < self.chars.len() && self.chars[j].is_whitespace() {
                            j+=1;
                        }
                        if j < self.chars.len() && self.chars[j].is_ascii_alphabetic() {
                            self.pos = j;
                            continue;
                        } else {
                            break;
                        }
                    } else {
                        break;
                    }
                }
                tokens.push(Token::Identifier(ident));
                continue;
            }
            match c {
                '+' => { tokens.push(Token::Plus); self.pos+=1; },
                '-' => { tokens.push(Token::Minus); self.pos+=1; },
                '*' => {
                    if self.peek_n(1) == Some('*') {
                        tokens.push(Token::StarStar);
                        self.pos+=2;
                    } else {
                        tokens.push(Token::Star);
                        self.pos+=1;
                    }
                },
                '/' => { tokens.push(Token::Slash); self.pos+=1; },
                '%' => { tokens.push(Token::Percent); self.pos+=1; },
                '^' => { tokens.push(Token::Caret); self.pos+=1; },
                '!' => { tokens.push(Token::Bang); self.pos+=1; },
                '(' => { tokens.push(Token::LParen); self.pos+=1; },
                ')' => { tokens.push(Token::RParen); self.pos+=1; },
                ',' => { tokens.push(Token::Comma); self.pos+=1; },
                _ => {
                    if c == '\t' {
                        return Err(CalcError::Syntax(format!("Unexpected token: '\t'")));
                    } else {
                        let mut unexpected = String::new();
                        unexpected.push(c);
                        self.pos+=1;
                        while self.pos < self.chars.len() {
                            let ch = self.chars[self.pos];
                            if ch.is_ascii_alphanumeric() {
                                unexpected.push(ch);
                                self.pos+=1;
                            } else {
                                break;
                            }
                        }
                        return Err(CalcError::Syntax(format!("Unexpected character '{}'", unexpected)));
                    }
                }
            }
        }
        tokens.push(Token::Eof);
        Ok(tokens)
    }
}

fn insert_implicit_mul(tokens: Vec<Token>) -> Vec<Token> {
    let mut out: Vec<Token> = Vec::new();
    let mut i = 0;
    while i < tokens.len() {
        let cur = tokens[i].clone();
        out.push(cur.clone());
        if i+1 < tokens.len() {
            let next = tokens[i+1].clone();
            if cur == Token::Eof || next == Token::Eof {
                i+=1;
                continue;
            }
            let left_is_number = matches!(cur, Token::Number(_, _));
            let left_is_const = matches!(&cur, Token::Identifier(s) if s=="pi" || s=="e");
            let left_is_underscore = matches!(cur, Token::Underscore);
            let left_is_rparen = matches!(cur, Token::RParen);
            let right_is_lparen = matches!(next, Token::LParen);
            let right_is_number = matches!(next, Token::Number(_, _));
            let right_is_underscore = matches!(next, Token::Underscore);
            let right_is_ident = matches!(next, Token::Identifier(_));
            let right_is_const = matches!(&next, Token::Identifier(s) if s=="pi" || s=="e");
            let right_is_func = if let Token::Identifier(s) = &next {
                matches!(s.as_str(), "sin"|"cos"|"tan"|"csc"|"sec"|"cot"|"sinh"|"cosh"|"tanh"|"asin"|"acos"|"atan"|"acsc"|"asec"|"acot"|"ln"|"log2"|"log10"|"sqrt"|"ceil"|"floor"|"abs"|"exp"|"exp2"|"rad"|"deg"|"round"|"log"|"nroot")
            } else { false };

            let mut insert = false;
            if left_is_number {
                if right_is_lparen || right_is_func || right_is_const || right_is_underscore || (right_is_ident && !right_is_const && !right_is_func) {
                    insert = true;
                }
                if right_is_ident && !right_is_func && !right_is_const {
                    insert = true;
                }
            } else if left_is_const {
                if right_is_number || right_is_underscore {
                    insert = true;
                }
            } else if left_is_underscore {
                if right_is_lparen || right_is_func || right_is_const || right_is_number || right_is_underscore || right_is_ident {
                    insert = true;
                }
            } else if left_is_rparen {
                if right_is_lparen {
                    insert = true;
                }
            }

            if insert {
                out.push(Token::Star);
            }
        }
        i+=1;
    }
    out
}

struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    angle_unit: AngleUnit,
    previous_ans: f64,
}

impl Parser {
    fn new(tokens: Vec<Token>, angle_unit: AngleUnit, previous_ans: f64) -> Self {
        Self { tokens, pos: 0, angle_unit, previous_ans }
    }

    fn peek(&self) -> &Token {
        self.tokens.get(self.pos).unwrap_or(&Token::Eof)
    }

    fn next(&mut self) -> Token {
        let t = self.tokens.get(self.pos).cloned().unwrap_or(Token::Eof);
        self.pos+=1;
        t
    }

    fn parse(&mut self) -> Result<f64, CalcError> {
        let result = self.parse_add_sub()?;
        match self.peek() {
            Token::Eof => Ok(result),
            Token::RParen => Ok(result),
            Token::Comma => Ok(result),
            _ => Err(CalcError::Parser("Too many operators, too few operands".to_string())),
        }
    }

    fn parse_add_sub(&mut self) -> Result<f64, CalcError> {
        let mut left = self.parse_mul_div()?;
        loop {
            match self.peek() {
                Token::Plus => {
                    self.next();
                    let right = self.parse_mul_div()?;
                    left = left + right;
                    if !left.is_finite() {
                        return Err(CalcError::Large);
                    }
                },
                Token::Minus => {
                    self.next();
                    let right = self.parse_mul_div()?;
                    left = left - right;
                    if !left.is_finite() {
                        return Err(CalcError::Large);
                    }
                },
                _ => break,
            }
        }
        Ok(left)
    }

    fn parse_mul_div(&mut self) -> Result<f64, CalcError> {
        let mut left = self.parse_power()?;
        loop {
            match self.peek() {
                Token::Star => {
                    self.next();
                    let right = self.parse_power()?;
                    left = left * right;
                    if !left.is_finite() {
                        return Err(CalcError::Large);
                    }
                },
                Token::Slash => {
                    self.next();
                    let right = self.parse_power()?;
                    if right == 0.0 {
                        return Err(CalcError::Math("Divide by zero error!".to_string()));
                    }
                    left = left / right;
                    if !left.is_finite() {
                        return Err(CalcError::Large);
                    }
                },
                Token::Percent => {
                    self.next();
                    let right = self.parse_power()?;
                    if right == 0.0 {
                        return Err(CalcError::Math("Divide by zero error!".to_string()));
                    }
                    left = left % right;
                    if !left.is_finite() {
                        return Err(CalcError::Large);
                    }
                },
                _ => break,
            }
        }
        Ok(left)
    }

    fn parse_power(&mut self) -> Result<f64, CalcError> {
        let left = self.parse_factorial()?;
        match self.peek() {
            Token::Caret | Token::StarStar => {
                self.next();
                let right = self.parse_power()?;
                let res = left.powf(right);
                if !res.is_finite() {
                    return Err(CalcError::Large);
                }
                Ok(res)
            },
            _ => Ok(left),
        }
    }

    fn parse_factorial(&mut self) -> Result<f64, CalcError> {
        let mut val = self.parse_unary()?;
        while matches!(self.peek(), Token::Bang) {
            self.next();
            if val < 0.0 || val.fract() != 0.0 {
                return Err(CalcError::Domain("Out of bounds!".to_string()));
            }
            let mut result = 1.0;
            let n = val as u64;
            for i in 2..=n {
                result *= i as f64;
                if !result.is_finite() {
                    return Err(CalcError::Large);
                }
            }
            val = result;
        }
        Ok(val)
    }

    fn parse_unary(&mut self) -> Result<f64, CalcError> {
        match self.peek() {
            Token::Plus => {
                self.next();
                self.parse_unary()
            },
            Token::Minus => {
                self.next();
                let v = self.parse_unary()?;
                Ok(-v)
            },
            _ => self.parse_primary(),
        }
    }

    fn parse_primary(&mut self) -> Result<f64, CalcError> {
        match self.peek().clone() {
            Token::Number(v, _) => {
                self.next();
                Ok(v)
            },
            Token::Underscore => {
                self.next();
                Ok(self.previous_ans)
            },
            Token::Identifier(name) => {
                if name == "pi" {
                    self.next();
                    Ok(std::f64::consts::PI)
                } else if name == "e" {
                    self.next();
                    Ok(std::f64::consts::E)
                } else {
                    let funcs_1 = ["sin","cos","tan","csc","sec","cot","sinh","cosh","tanh","asin","acos","atan","acsc","asec","acot","ln","log2","log10","sqrt","ceil","floor","abs","exp","exp2","rad","deg","round"];
                    let funcs_2 = ["log","nroot"];
                    if funcs_1.contains(&name.as_str()) || funcs_2.contains(&name.as_str()) {
                        self.next();
                        match self.peek() {
                            Token::LParen => {
                                self.next();
                                if funcs_1.contains(&name.as_str()) {
                                    if matches!(self.peek(), Token::RParen) {
                                        self.next();
                                        return Err(CalcError::Parser(format!("To few arguments for function, need 1")));
                                    }
                                    let arg = self.parse_add_sub()?;
                                    match self.peek() {
                                        Token::RParen => { self.next(); },
                                        Token::Comma => {
                                            return Err(CalcError::Parser("Too many operators, too few operands".to_string()));
                                        },
                                        _ => {
                                            return Err(CalcError::Parser("Too many operators, too few operands".to_string()));
                                        }
                                    }
                                    return self.eval_func_1(&name, arg);
                                } else {
                                    if matches!(self.peek(), Token::RParen) {
                                        self.next();
                                        return Err(CalcError::Parser(format!("To few arguments for function, need 2")));
                                    }
                                    let arg1 = self.parse_add_sub()?;
                                    match self.peek() {
                                        Token::Comma => {
                                            self.next();
                                            match self.peek() {
                                                Token::Plus | Token::Minus => {
                                                    return Err(CalcError::Parser(format!("To few arguments for function, need 2")));
                                                },
                                                _ => {}
                                            }
                                            if matches!(self.peek(), Token::RParen) {
                                                self.next();
                                                return Err(CalcError::Parser(format!("To few arguments for function, need 2")));
                                            }
                                            let arg2 = self.parse_add_sub()?;
                                            match self.peek() {
                                                Token::RParen => { self.next(); },
                                                Token::Comma => {
                                                    return Err(CalcError::Parser("Too many operators, too few operands".to_string()));
                                                },
                                                _ => {
                                                    return Err(CalcError::Parser("Too many operators, too few operands".to_string()));
                                                }
                                            }
                                            return self.eval_func_2(&name, arg1, arg2);
                                        },
                                        Token::RParen => {
                                            self.next();
                                            return Err(CalcError::Parser(format!("To few arguments for function, need 2")));
                                        },
                                        _ => {
                                            return Err(CalcError::Parser("Too many operators, too few operands".to_string()));
                                        }
                                    }
                                }
                            },
                            _ => {
                                return Err(CalcError::Syntax(format!("Function '{}' expected parentheses", name)));
                            }
                        }
                    } else {
                        let next_is_lparen = matches!(self.tokens.get(self.pos+1), Some(Token::LParen));
                        if next_is_lparen {
                            return Err(CalcError::Syntax(format!("Unknown function '{}'", name)));
                        } else {
                            return Err(CalcError::Parser("Too many operators, too few operands".to_string()));
                        }
                    }
                }
            },
            Token::LParen => {
                self.next();
                if matches!(self.peek(), Token::RParen) {
                    self.next();
                    return Err(CalcError::Parser("Too many operators, too few operands".to_string()));
                }
                let v = self.parse_add_sub()?;
                match self.peek() {
                    Token::RParen => { self.next(); Ok(v) },
                    _ => Err(CalcError::Syntax("Mismatched parentheses!".to_string())),
                }
            },
            Token::RParen => Err(CalcError::Syntax("Mismatched parentheses!".to_string())),
            Token::Comma => Err(CalcError::Parser("Too many operators, too few operands".to_string())),
            Token::Plus | Token::Minus | Token::Star | Token::Slash | Token::Percent | Token::Caret | Token::StarStar | Token::Bang => Err(CalcError::Parser("Too many operators, too few operands".to_string())),
            Token::Eof => Err(CalcError::Parser("Too many operators, too few operands".to_string())),
        }
    }

    fn eval_func_1(&self, name: &str, arg: f64) -> Result<f64, CalcError> {
        let res = match name {
            "sin" => {
                let rad = match self.angle_unit {
                    AngleUnit::Degree => arg * std::f64::consts::PI / 180.0,
                    AngleUnit::Radian => arg,
                    AngleUnit::Gradian => arg * std::f64::consts::PI / 180.0,
                };
                rad.sin()
            },
            "cos" => {
                let rad = match self.angle_unit {
                    AngleUnit::Degree => arg * std::f64::consts::PI / 180.0,
                    AngleUnit::Radian => arg,
                    AngleUnit::Gradian => arg * std::f64::consts::PI / 180.0,
                };
                rad.cos()
            },
            "tan" => {
                let rad = match self.angle_unit {
                    AngleUnit::Degree => arg * std::f64::consts::PI / 180.0,
                    AngleUnit::Radian => arg,
                    AngleUnit::Gradian => arg * std::f64::consts::PI / 180.0,
                };
                rad.tan()
            },
            "csc" => {
                let rad = match self.angle_unit {
                    AngleUnit::Degree => arg * std::f64::consts::PI / 180.0,
                    AngleUnit::Radian => arg,
                    AngleUnit::Gradian => arg * std::f64::consts::PI / 180.0,
                };
                let s = rad.sin();
                if s.abs() < 1e-15 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                1.0 / s
            },
            "sec" => {
                let rad = match self.angle_unit {
                    AngleUnit::Degree => arg * std::f64::consts::PI / 180.0,
                    AngleUnit::Radian => arg,
                    AngleUnit::Gradian => arg * std::f64::consts::PI / 180.0,
                };
                let c = rad.cos();
                if c.abs() < 1e-15 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                1.0 / c
            },
            "cot" => {
                let rad = match self.angle_unit {
                    AngleUnit::Degree => arg * std::f64::consts::PI / 180.0,
                    AngleUnit::Radian => arg,
                    AngleUnit::Gradian => arg * std::f64::consts::PI / 180.0,
                };
                let t = rad.tan();
                if t.abs() < 1e-15 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                1.0 / t
            },
            "sinh" => arg.sinh(),
            "cosh" => arg.cosh(),
            "tanh" => arg.tanh(),
            "asin" => {
                if arg < -1.0 || arg > 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                arg.asin()
            },
            "acos" => {
                if arg < -1.0 || arg > 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                arg.acos()
            },
            "atan" => arg.atan(),
            "acsc" => {
                if arg.abs() < 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                (1.0 / arg).asin()
            },
            "asec" => {
                if arg.abs() < 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                (1.0 / arg).acos()
            },
            "acot" => {
                if arg == 0.0 {
                    std::f64::consts::PI / 2.0
                } else {
                    (1.0 / arg).atan()
                }
            },
            "ln" => {
                if arg <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                arg.ln()
            },
            "log2" => {
                if arg <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                arg.log2()
            },
            "log10" => {
                if arg <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                arg.log10()
            },
            "sqrt" => {
                if arg < 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                arg.sqrt()
            },
            "ceil" => arg.ceil(),
            "floor" => arg.floor(),
            "abs" => arg.abs(),
            "exp" => arg.exp(),
            "exp2" => arg.exp2(),
            "rad" => arg * std::f64::consts::PI / 180.0,
            "deg" => arg * 180.0 / std::f64::consts::PI,
            "round" => {
                if arg.is_sign_positive() {
                    (arg + 0.5).floor()
                } else {
                    (arg - 0.5).ceil()
                }
            },
            _ => return Err(CalcError::Syntax(format!("Unknown function '{}'", name))),
        };
        if !res.is_finite() {
            return Err(CalcError::Large);
        }
        Ok(res)
    }

    fn eval_func_2(&self, name: &str, a: f64, b: f64) -> Result<f64, CalcError> {
        let res = match name {
            "log" => {
                if a <= 0.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                if b == 1.0 { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                if b == 0.0 {
                    -0.0
                } else {
                    if b <= 0.0 {
                        return Err(CalcError::Domain("Out of bounds!".to_string()));
                    }
                    a.ln() / b.ln()
                }
            },
            "nroot" => {
                if a < 0.0 {
                    return Err(CalcError::Domain("Out of bounds!".to_string()));
                }
                if b == 0.0 {
                    if a == 0.0 { 0.0 }
                    else if a == 1.0 { 1.0 }
                    else { return Err(CalcError::Domain("Out of bounds!".to_string())); }
                } else {
                    a.powf(1.0 / b)
                }
            },
            _ => return Err(CalcError::Syntax(format!("Unknown function '{}'", name))),
        };
        if res == -0.0 { return Ok(res); }
        if !res.is_finite() {
            return Err(CalcError::Large);
        }
        Ok(res)
    }
}

fn auto_balance(s: &str) -> Result<String, CalcError> {
    let mut open = 0;
    let mut close = 0;
    for c in s.chars() {
        if c == '(' { open+=1; }
        else if c == ')' { close+=1; }
    }
    if close > open {
        return Err(CalcError::Syntax("Mismatched parentheses!".to_string()));
    }
    let mut res = s.to_string();
    for _ in 0..(open-close) {
        res.push(')');
    }
    Ok(res)
}

fn eval_expression(expr: &str, angle_unit: AngleUnit, prev: f64) -> Result<f64, CalcError> {
    let trimmed = expr.trim();
    if trimmed.is_empty() {
        return Ok(0.0);
    }
    let balanced = auto_balance(trimmed)?;
    let mut lexer = Lexer::new(&balanced);
    let tokens = lexer.tokenize()?;
    let tokens = insert_implicit_mul(tokens);
    let mut parser = Parser::new(tokens, angle_unit, prev);
    parser.parse()
}

fn format_output(value: f64, base: u32, fix: usize) -> String {
    if base == 1 {
        let rounded_str = format!("{:.fix$}", value);
        let rounded_val: f64 = rounded_str.parse().unwrap_or(value);
        let abs_rounded = rounded_val.abs();
        let int_part = abs_rounded.trunc() as u64;
        if int_part != 0 {
            loop {}
        }
        let int_str = "0".to_string();
        let frac = abs_rounded.fract();
        let frac_is_zero = frac < 1e-12;
        let frac_str = if frac_is_zero {
            "0".to_string()
        } else {
            "0".repeat(fix)
        };
        let sign = if rounded_val.is_sign_negative() { "-" } else { "" };
        let grouped_int = format_int_non10(&int_str, sign, base);
        return format!("{}.{}", grouped_int, frac_str);
    }

    if base == 10 {
        let formatted = format!("{:.fix$}", value);
        let (sign_str, rest) = if formatted.starts_with('-') {
            ("-", &formatted[1..])
        } else {
            ("", formatted.as_str())
        };
        let parts: Vec<&str> = rest.split('.').collect();
        let int_part = parts[0];
        let frac_part = if parts.len() > 1 { parts[1] } else { "" };
        let grouped_int = group_int_base10(int_part);
        if fix == 0 {
            format!("{}{}", sign_str, grouped_int)
        } else {
            format!("{}{}.{}", sign_str, grouped_int, frac_part)
        }
    } else {
        let rounded_str = format!("{:.fix$}", value);
        let rounded_val: f64 = rounded_str.parse().unwrap_or(value);
        let is_neg = rounded_val.is_sign_negative();
        let abs_val = rounded_val.abs();
        let int_part_f = abs_val.trunc();
        let frac_part_f = abs_val.fract();

        let int_str = convert_int_to_base(int_part_f, base);

        let mut frac_digits: Vec<char> = Vec::new();
        let mut frac = frac_part_f;
        for _ in 0..fix {
            frac *= base as f64;
            let digit = frac.trunc() as u32;
            let ch = digit_to_char(digit);
            frac_digits.push(ch);
            frac -= digit as f64;
            if frac < 1e-12 {
                break;
            }
        }
        if frac_digits.is_empty() {
            frac_digits.push('0');
        } else {
            while frac_digits.len() > 1 && *frac_digits.last().unwrap() == '0' {
                frac_digits.pop();
            }
        }
        let frac_str: String = frac_digits.into_iter().collect();
        let sign_str = if is_neg { "-" } else { "" };
        let grouped_int = format_int_non10(&int_str, sign_str, base);
        format!("{}.{}", grouped_int, frac_str)
    }
}

fn group_int_base10(s: &str) -> String {
    if s.is_empty() { return "0".to_string(); }
    let mut result = String::new();
    let mut count = 0;
    for ch in s.chars().rev() {
        if count != 0 && count % 3 == 0 {
            result.push(',');
        }
        result.push(ch);
        count+=1;
    }
    result.chars().rev().collect()
}

fn convert_int_to_base(val: f64, base: u32) -> String {
    if val == 0.0 {
        return "0".to_string();
    }
    if val <= 9_007_199_254_740_992.0 {
        let mut n = val as u128;
        let mut digits: Vec<char> = Vec::new();
        while n > 0 {
            let d = (n % base as u128) as u32;
            digits.push(digit_to_char(d));
            n /= base as u128;
        }
        digits.into_iter().rev().collect()
    } else {
        let mut n = val;
        let mut digits: Vec<char> = Vec::new();
        while n >= 1.0 {
            let rem = (n % base as f64) as u32;
            digits.push(digit_to_char(rem));
            n = (n / base as f64).trunc();
            if digits.len() > 1000 { break; }
        }
        if digits.is_empty() { return "0".to_string(); }
        digits.into_iter().rev().collect()
    }
}

fn digit_to_char(d: u32) -> char {
    if d < 10 {
        (b'0' + d as u8) as char
    } else {
        (b'A' + (d - 10) as u8) as char
    }
}

fn format_int_non10(int_str: &str, sign: &str, _base: u32) -> String {
    let combined = format!("{}{}", sign, int_str);
    let len = combined.chars().count();
    let padded: String = if len < 10 {
        let spaces = " ".repeat(10 - len);
        format!("{}{}", spaces, combined)
    } else {
        combined
    };
    let chars: Vec<char> = padded.chars().collect();
    let mut groups: Vec<String> = Vec::new();
    let mut i = chars.len();
    while i > 0 {
        let start = if i >= 3 { i-3 } else { 0 };
        let group: String = chars[start..i].iter().collect();
        groups.push(group);
        i = start;
    }
    groups.reverse();
    groups.join(",")
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let config_res = parse_args(&args);
    let config = match config_res {
        Ok(c) => c,
        Err(e) => {
            eprint!("{}", e);
            std::process::exit(2);
        }
    };

    if config.help {
        print_help();
        return;
    }
    if config.version {
        print_version_fn();
        return;
    }

    if let Some(input) = config.input {
        let trimmed = input.trim();
        if trimmed.is_empty() {
            let home = env::var("HOME").unwrap_or_else(|_| "/root".to_string());
            let prev_path = PathBuf::from(format!("{}/.cache/eva/previous_ans.txt", home));
            if !prev_path.exists() {
                println!("No previous history.");
            }
            return;
        }
        let prev = 0.0;
        match eval_expression(&input, config.angle_unit.clone(), prev) {
            Ok(val) => {
                let out = format_output(val, config.base, config.fix);
                println!("{}", out);
            },
            Err(e) => {
                match e {
                    CalcError::NoHistory => println!("{}", e.to_string()),
                    _ => eprintln!("{}", e.to_string()),
                }
            }
        }
    } else {
        let home = env::var("HOME").unwrap_or_else(|_| "/root".to_string());
        let cache_dir = PathBuf::from(format!("{}/.cache/eva", home));
        let share_dir = PathBuf::from(format!("{}/.local/share/eva", home));
        let prev_path = cache_dir.join("previous_ans.txt");
        let history_path = share_dir.join("history.txt");

        let has_history = prev_path.exists();
        if !has_history {
            println!("No previous history.");
        }

        let mut prev_ans: f64 = 0.0;
        if let Ok(content) = fs::read_to_string(&prev_path) {
            if let Ok(v) = content.trim().parse::<f64>() {
                prev_ans = v;
            }
        }

        let _ = fs::create_dir_all(&cache_dir);
        let _ = fs::create_dir_all(&share_dir);
        if !history_path.exists() {
            let _ = fs::write(&history_path, "#V2\n");
        }

        let mut stdin_content = String::new();
        if io::stdin().read_to_string(&mut stdin_content).is_ok() {
            for line in stdin_content.lines() {
                let line_trimmed = line.trim();
                if line_trimmed.is_empty() {
                    let val = 0.0;
                    let out = format_output(val, config.base, config.fix);
                    println!("{}", out);
                    prev_ans = val;
                    let _ = fs::write(&prev_path, format!("{}", prev_ans));
                    continue;
                }
                if let Ok(mut file) = fs::OpenOptions::new().append(true).open(&history_path) {
                    let _ = writeln!(file, "{}", line);
                }

                match eval_expression(line, config.angle_unit.clone(), prev_ans) {
                    Ok(val) => {
                        let out = format_output(val, config.base, config.fix);
                        println!("{}", out);
                        prev_ans = val;
                        let _ = fs::write(&prev_path, format!("{}", prev_ans));
                    },
                    Err(e) => {
                        println!("{}", e.to_string());
                    }
                }
            }
        }
    }
}
